function AuthProvider({ children }) {
  const [user, setUser] = useState(null)
  const [loading, setLoading] = useState(Boolean(localStorage.getItem(TOKEN_KEY)))
  useEffect(() => {
    if (!localStorage.getItem(TOKEN_KEY)) return
    authApi.me().then(setUser).catch(() => localStorage.removeItem(TOKEN_KEY)).finally(() => setLoading(false))
  }, [])
  const login = async (body) => { const result = await authApi.login(body); localStorage.setItem(TOKEN_KEY, result.access_token); setUser(result.user); return result }
  const register = async (body) => { const result = await authApi.register(body); localStorage.setItem(TOKEN_KEY, result.access_token); setUser(result.user); return result }
  const logout = () => { localStorage.removeItem(TOKEN_KEY); setUser(null) }
  const value = useMemo(() => ({ user, loading, login, register, logout }), [user, loading])
  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

