function Chat() {
  const [threads, setThreads] = useState(demoThreads); const [active, setActive] = useState(null); const [messages, setMessages] = useState([]); const [input, setInput] = useState(''); const [thinking, setThinking] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('')
  const loadThreads = () => api('/mental-health/threads').then((data) => setThreads(data.threads || [])).catch(() => setThreads(demoThreads))
  useEffect(() => { loadThreads() }, [])
  const selectThread = (id) => { setActive(id); if (id === 'demo') return setMessages([{ is_user: false, content: 'Welcome back. What would feel supportive to explore today?' }]); api(`/mental-health/threads/${id}`).then((data) => setMessages(data.messages || [])).catch((err) => setError(err.message)) }
  const send = async (event) => {
    event.preventDefault(); if (!input.trim() || busy) return
    const text = input.trim(); setInput(''); setBusy(true); setError(''); setMessages((current) => [...current, { is_user: true, content: text }]); setThinking('Opening a secure space…'); let reply = ''; let threadId = active
    try {
      await streamChat(text, active, (eventData) => { if (eventData.type === 'thread_id') threadId = eventData.data; if (eventData.type === 'thinking') setThinking(eventData.data); if (eventData.type === 'token') { reply += eventData.data; setMessages((current) => { const last = current[current.length - 1]; if (last && !last.is_user && last.streaming) return [...current.slice(0, -1), { ...last, content: reply }]; return [...current, { is_user: false, content: reply, streaming: true }] }) } if (eventData.type === 'complete') { setActive(threadId); setThinking(''); setMessages((current) => current.map((item) => ({ ...item, streaming: false }))) } if (eventData.type === 'error') setError(eventData.data) })
      loadThreads()
    } catch (err) { setError('Demo mode: the API is offline. Your check-in is still safe here.'); setMessages((current) => [...current, { is_user: false, content: 'I’m here with you. Take one slow breath, then name the smallest part of this moment that feels manageable.' }]); if (err) setThinking('') } finally { setBusy(false); setThinking('') }
  }
  const newChat = () => { setActive(null); setMessages([]); setError('') }
  return <div className="grid min-h-[calc(100vh-152px)] gap-5 xl:grid-cols-[250px_1fr]"><section className="glass hidden rounded-2xl p-4 xl:block"><div className="flex items-center justify-between px-2"><p className="font-mono text-[10px] uppercase tracking-[.2em] text-slate-500">Threads</p><button onClick={newChat} className="text-mint"><Plus size={16} /></button></div><Button onClick={newChat} variant="secondary" className="mt-4 w-full text-xs"><Plus size={14} /> New check-in</Button><div className="scrollbar mt-5 max-h-[calc(100vh-290px)] space-y-1 overflow-y-auto">{threads.map((thread) => <button key={thread.id} onClick={() => selectThread(thread.id)} className={`w-full rounded-xl p-3 text-left transition ${active === thread.id ? 'bg-mint/10 text-mint' : 'text-slate-500 hover:bg-white/[.04]'}`}><p className="truncate text-xs font-medium">{thread.title}</p><p className="mt-1 truncate text-[10px] text-slate-600">{thread.last_message || 'No messages yet'}</p></button>)}</div></section><section className="glass flex min-h-[600px] flex-col rounded-2xl"><div className="flex items-center gap-3 border-b border-white/[.07] p-5"><span className="grid h-9 w-9 place-items-center rounded-xl bg-mint/10 text-mint"><Brain size={18} /></span><div><h2 className="font-display font-semibold">CalmBot <span className="ml-2 rounded-full bg-mint/10 px-2 py-1 font-mono text-[9px] uppercase tracking-wider text-mint">online</span></h2><p className="text-[11px] text-slate-600">A private place to say the unsaid.</p></div><button onClick={newChat} className="ml-auto text-slate-600 xl:hidden"><Plus size={18} /></button></div>{error && <div className="px-5 pt-4"><ErrorNote message={error} /></div>}<div className="scrollbar flex-1 space-y-5 overflow-y-auto p-5 sm:p-8">{!messages.length && <div className="flex h-full min-h-[400px] flex-col items-center justify-center text-center"><div className="mb-5 grid h-16 w-16 place-items-center rounded-2xl border border-mint/20 bg-mint/5 text-mint"><Sparkles size={25} /></div><h3 className="font-display text-2xl font-semibold">What’s on your mind?</h3><p className="mt-2 max-w-sm text-sm leading-relaxed text-slate-500">There’s no perfect way to start. Just bring what’s real.</p><div className="mt-7 flex flex-wrap justify-center gap-2">{['I feel a little off today', 'Help me slow down', 'I need a fresh perspective'].map((prompt) => <button key={prompt} onClick={() => setInput(prompt)} className="rounded-full border border-white/10 px-3 py-2 text-xs text-slate-400 hover:border-mint/30 hover:text-mint">{prompt}</button>)}</div></div>}{messages.map((message, index) => <div key={`${message.content}-${index}`} className={`flex gap-3 ${message.is_user ? 'justify-end' : ''}`}><div className={`max-w-[85%] rounded-2xl px-4 py-3 text-sm leading-relaxed ${message.is_user ? 'rounded-br-sm bg-mint text-void' : 'rounded-bl-sm border border-white/[.08] bg-white/[.04] text-slate-300'}`}>{message.content}</div></div>)}{thinking && <div className="flex items-center gap-2 text-xs text-slate-600"><Loader2 className="animate-spin text-mint" size={13} /> {thinking}</div>}</div><form onSubmit={send} className="border-t border-white/[.07] p-4"><div className="flex items-center gap-3 rounded-xl border border-white/10 bg-black/20 px-4 focus-within:border-mint/40"><input value={input} onChange={(e) => setInput(e.target.value)} placeholder="Say what’s true…" className="min-w-0 flex-1 bg-transparent py-3 text-sm text-white outline-none placeholder:text-slate-700" /><button disabled={busy || !input.trim()} className="text-mint disabled:opacity-30"><Send size={17} /></button></div><p className="mt-2 text-center font-mono text-[9px] text-slate-700">ZenHeaven is a support tool, not a replacement for professional care.</p></form></section></div>
}

function Journal() {
  const [entries, setEntries] = useState([]); const [prompts, setPrompts] = useState([]); const [content, setContent] = useState(''); const [mood, setMood] = useState(''); const [analysis, setAnalysis] = useState(null); const [busy, setBusy] = useState(false); const [error, setError] = useState('')
  const load = () => Promise.all([api('/journal/entries'), api('/journal/prompts')]).then(([items, promptData]) => { setEntries(items || []); setPrompts(promptData || []) }).catch((err) => { setEntries([]); setPrompts([{ prompt: 'What made you smile today?', category: 'gratitude' }, { prompt: 'What would feel like enough today?', category: 'reflection' }, { prompt: 'Describe a moment of calm.', category: 'mindfulness' }]); setError(err.message) })
  useEffect(() => { load() }, [])
  const analyze = async () => { if (!content.trim()) return; setBusy(true); try { setAnalysis(await api('/journal/analyze-mood', { method: 'POST', body: { content } })) } catch (err) { setAnalysis({ mood: 'reflective', mood_description: 'Your words are worth noticing. Give yourself a little room to listen.', suggestions: ['Take three slow breaths.', 'Write one kind next step.'] }); setError(err.message) } finally { setBusy(false) } }
  const save = async () => { if (!content.trim()) return; setBusy(true); try { await api('/journal/entries', { method: 'POST', body: { content, mood: mood || analysis?.mood || undefined, tags: [] } }); setContent(''); setMood(''); setAnalysis(null); load() } catch (err) { setError(err.message) } finally { setBusy(false) } }
  const remove = (id) => api(`/journal/entries/${id}`, { method: 'DELETE' }).then(load).catch((err) => setError(err.message))
  return <><PageTitle eyebrow="Journal / your signal" title="Write it down." copy="A place to turn the noise into something you can see." action={<Button onClick={() => document.getElementById('entry')?.focus()} variant="secondary"><PenLine size={15} /> New entry</Button>} />{error && <ErrorNote message={error} retry={load} />}<div className="grid gap-6 xl:grid-cols-[1.15fr_.85fr]"><section className="glass rounded-2xl p-6"><div className="flex items-center justify-between"><p className="font-mono text-[10px] uppercase tracking-[.2em] text-mint">New entry</p><span className="font-mono text-[10px] text-slate-600">{content.length} chars</span></div><textarea id="entry" value={content} onChange={(e) => setContent(e.target.value)} placeholder="What is present for you right now?" className="mt-5 min-h-[260px] w-full resize-none bg-transparent font-display text-2xl leading-relaxed text-slate-200 outline-none placeholder:text-slate-700" /><div className="flex flex-wrap items-end justify-between gap-4 border-t border-white/[.07] pt-4"><div><label className="font-mono text-[9px] uppercase tracking-widest text-slate-600">Optional mood</label><div className="mt-2 flex flex-wrap gap-2">{['calm', 'hopeful', 'anxious', 'grateful', 'overwhelmed'].map((item) => <button type="button" key={item} onClick={() => setMood(item)} className={`rounded-full border px-3 py-1.5 text-xs transition ${mood === item ? 'border-mint/50 bg-mint/10 text-mint' : 'border-white/10 text-slate-500'}`}>{item}</button>)}</div></div><div className="flex gap-2"><Button onClick={analyze} disabled={busy || !content.trim()} variant="secondary">{busy ? <Loader2 className="animate-spin" size={14} /> : <Sparkles size={14} />} Reflect</Button><Button onClick={save} disabled={busy || !content.trim()}><Check size={14} /> Save entry</Button></div></div>{analysis && <div className="mt-5 rounded-xl border border-lavender/20 bg-lavender/[.06] p-4"><div className="flex items-center gap-2 text-lavender"><Sparkles size={15} /><span className="font-mono text-[10px] uppercase tracking-widest">Reflection</span><span className="ml-auto rounded-full bg-lavender/10 px-2 py-1 text-xs">{analysis.mood}</span></div><p className="mt-3 text-sm leading-relaxed text-slate-400">{analysis.mood_description}</p>{analysis.suggestions?.length > 0 && <ul className="mt-3 space-y-1 text-xs text-slate-500">{analysis.suggestions.map((item) => <li key={item}>↳ {item}</li>)}</ul>}</div>}</section><section className="glass rounded-2xl p-6"><p className="font-mono text-[10px] uppercase tracking-[.2em] text-lavender">Prompt pool</p><h2 className="mt-2 font-display text-2xl font-semibold">A way in.</h2><div className="mt-6 space-y-2">{prompts.slice(0, 5).map((prompt) => <button key={prompt.prompt} onClick={() => setContent(prompt.prompt + '\n\n')} className="group flex w-full items-start gap-3 rounded-xl border border-white/[.06] p-3 text-left hover:border-lavender/25"><span className="text-lavender">✦</span><span className="text-sm text-slate-400 group-hover:text-slate-200">{prompt.prompt}<small className="mt-1 block font-mono text-[9px] uppercase tracking-widest text-slate-700">{prompt.category}</small></span></button>)}</div></section></div><section className="mt-6"><div className="mb-4 flex items-end justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-mint">Archive</p><h2 className="mt-2 font-display text-2xl font-semibold">Recent reflections</h2></div><span className="font-mono text-xs text-slate-600">{entries.length} entries</span></div>{entries.length ? <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{entries.map((entry) => <article key={entry._id || entry.id} className="glass group rounded-2xl p-5"><div className="flex items-start justify-between"><span className="rounded-full bg-mint/10 px-2 py-1 font-mono text-[9px] uppercase tracking-wider text-mint">{entry.mood || 'unmapped'}</span><button onClick={() => remove(entry._id || entry.id)} className="text-slate-700 hover:text-rose-300"><Trash2 size={14} /></button></div><h3 className="mt-4 font-display font-semibold text-slate-200">{entry.title || 'Untitled reflection'}</h3><p className="mt-2 line-clamp-3 text-sm leading-relaxed text-slate-500">{entry.content}</p><p className="mt-5 font-mono text-[9px] uppercase tracking-wider text-slate-700">{entry.created_at ? new Date(entry.created_at).toLocaleDateString() : 'Recently'}</p></article>)}</div> : <EmptyState icon={PenLine} title="The page is yours." copy="Your saved reflections will gather here over time." />}</section></>
}

function Books() {
  const { user } = useAuth(); const [books, setBooks] = useState(demoBooks); const [query, setQuery] = useState(''); const [mood, setMood] = useState('balanced'); const [busy, setBusy] = useState(true); const [error, setError] = useState('')
  const load = () => { setBusy(true); api(`/books/recommend-by-mood${user?.id ? `?user_id=${user.id}` : ''}`).then((data) => { setBooks(data.books || demoBooks); setMood(data.mood || 'balanced') }).catch((err) => { setBooks(demoBooks); setError(err.message) }).finally(() => setBusy(false)) }
  useEffect(() => { load() }, [])
  const search = (event) => { event.preventDefault(); if (!query.trim()) return load(); setBusy(true); api(`/books/search?q=${encodeURIComponent(query)}&max_results=10`).then((data) => setBooks(data.books || [])).catch((err) => setError(err.message)).finally(() => setBusy(false)) }
  return <><PageTitle eyebrow="Library / curated for you" title="Pages that meet you." copy={`Because you’re feeling ${mood}, these reads were selected for this moment.`} action={<form onSubmit={search} className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[.03] px-3"><Search size={15} className="text-slate-600" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search the library" className="w-40 bg-transparent py-2.5 text-xs outline-none placeholder:text-slate-700 sm:w-52" /></form>} />{error && <ErrorNote message={error} retry={load} />}{busy ? <div className="flex justify-center py-24"><Loader2 className="animate-spin text-mint" /></div> : <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">{books.map((book) => <BookCard key={book.id} book={book} />)}</div>}{!busy && !books.length && <EmptyState icon={BookOpen} title="No pages found" copy="Try another search or return to your mood-based picks." />}</>
}
function BookCard({ book }) { const [more, setMore] = useState(null); const getMore = () => api(`/books/recommend/${book.id}`).then(setMore).catch(() => {}) ; return <article className="group overflow-hidden rounded-2xl border border-white/[.08] bg-[#0b1a22] transition hover:-translate-y-1 hover:border-mint/30"><div className="relative h-48 overflow-hidden bg-gradient-to-br from-lavender/20 to-mint/10">{book.image_url ? <img src={book.image_url} alt="" className="h-full w-full object-cover opacity-80 transition duration-500 group-hover:scale-105" /> : <div className="grid h-full place-items-center text-mint"><BookOpen size={32} /></div>}<div className="absolute inset-0 bg-gradient-to-t from-[#0b1a22] to-transparent" /></div><div className="p-4"><p className="line-clamp-2 font-display font-semibold text-slate-200">{book.title}</p><p className="mt-1 text-xs text-slate-500">{book.author}</p><p className="mt-3 line-clamp-2 text-xs leading-relaxed text-slate-600">{book.description}</p><button onClick={getMore} className="mt-4 flex items-center gap-1 text-xs font-semibold text-mint">Find adjacent reads <ArrowRight size={12} /></button>{more && <p className="mt-2 text-[10px] text-lavender">{more.recommended_books?.length || 0} similar paths found</p>}</div></article> }

function Music() {
  const demoSongs = ['Weightless — Marconi Union', 'Bloom — ODESZA', 'Awake — Tycho', 'Riverside — Agnes Obel', 'Holocene — Bon Iver']; const [songs, setSongs] = useState(demoSongs); const [selected, setSelected] = useState(''); const [recommendations, setRecommendations] = useState([]); const [busy, setBusy] = useState(true); const [error, setError] = useState('')
  useEffect(() => { api('/songs').then((data) => setSongs(data.songs || demoSongs)).catch((err) => setError(err.message)).finally(() => setBusy(false)) }, [])
  const recommend = () => { if (!selected) return; setBusy(true); api(`/recommend?song=${encodeURIComponent(selected)}`).then((data) => setRecommendations(data.recommendations || [])).catch(() => setRecommendations(songs.slice(0, 4).map((song, index) => ({ name: song, artist: ['Marconi Union', 'ODESZA', 'Tycho', 'Agnes Obel'][index] })))).finally(() => setBusy(false)) }
  return <><PageTitle eyebrow="Sound room / shift your state" title="A frequency for now." copy="Pick a track. We’ll find the next five places your attention might want to go." /><div className="grid gap-6 xl:grid-cols-[.75fr_1.25fr]"><section className="glass rounded-2xl p-6"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-mint/10 text-mint"><Radio size={18} /></span><div><p className="font-display font-semibold">Choose an anchor</p><p className="text-xs text-slate-600">What sounds like you?</p></div></div><select value={selected} onChange={(e) => setSelected(e.target.value)} className="mt-7 w-full rounded-xl border border-white/10 bg-[#0a171f] px-4 py-3 text-sm text-slate-300 outline-none"><option value="">Select a song</option>{songs.slice(0, 200).map((song) => <option key={song} value={song}>{song}</option>)}</select><Button onClick={recommend} disabled={!selected || busy} className="mt-3 w-full">{busy ? <Loader2 className="animate-spin" size={15} /> : <Sparkles size={15} />} Build my listening path</Button>{error && <p className="mt-4 text-xs text-rose-300">Demo library active · API says {error}</p>}<div className="mt-8 rounded-xl border border-lavender/20 bg-lavender/[.05] p-4"><p className="font-mono text-[9px] uppercase tracking-[.2em] text-lavender">Listening note</p><p className="mt-2 text-sm leading-relaxed text-slate-400">Music can be a handrail. Let it hold the moment without asking it to fix everything.</p></div></section><section><div className="mb-4 flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-mint">Your orbit</p><h2 className="mt-2 font-display text-2xl font-semibold">{recommendations.length ? 'Next in the sequence' : 'Your next sequence'}</h2></div><Headphones className="text-slate-700" size={20} /></div>{recommendations.length ? <div className="space-y-2">{recommendations.map((song, i) => <div key={`${song.name}-${i}`} className="glass group flex items-center gap-4 rounded-xl p-3"><div className="grid h-14 w-14 place-items-center rounded-lg bg-gradient-to-br from-mint/20 to-lavender/20 text-mint"><Play size={16} fill="currentColor" /></div><div className="flex-1"><p className="text-sm font-medium text-slate-200">{song.name}</p><p className="mt-1 text-xs text-slate-500">{song.artist}</p></div><span className="font-mono text-[10px] text-slate-700">0{i + 1}</span></div>)}</div> : <EmptyState icon={Music2} title="The quiet before the first track" copy={busy ? 'Loading your available library…' : 'Choose an anchor track to generate a listening path.'} />}</section></div></>
}

function Therapists() {
  const { user } = useAuth(); const [therapists, setTherapists] = useState(demoTherapists); const [appointments, setAppointments] = useState([]); const [selected, setSelected] = useState(null); const [slot, setSlot] = useState(null); const [busy, setBusy] = useState(true); const [error, setError] = useState(''); const [notes, setNotes] = useState('')
  const load = () => Promise.all([api('/therapists/'), api(`/therapists/appointments/user/${user?.id}`)]).then(([people, booked]) => { setTherapists(people || demoTherapists); setAppointments(booked || []) }).catch((err) => { setTherapists(demoTherapists); setError(err.message) }).finally(() => setBusy(false))
  useEffect(() => { load() }, [])
  const open = (person) => { setSelected(person); setSlot(null); api(`/therapists/${person._id || person.id}`).then(setSelected).catch(() => {}) }
  const book = async () => { if (!selected || !slot) return; setBusy(true); try { await api('/therapists/appointments', { method: 'POST', body: { user_id: user.id, therapist_id: selected._id || selected.id, date: slot.start_time, start_time: slot.start_time, end_time: slot.end_time, notes, session_type: 'video' } }); setSelected(null); setNotes(''); load() } catch (err) { setError(err.message) } finally { setBusy(false) } }
  const cancel = (id) => api(`/therapists/appointments/${id}`, { method: 'DELETE' }).then(load).catch((err) => setError(err.message))
  const demoSlots = [1, 2, 3].map((day) => ({ start_time: new Date(Date.now() + day * 86400000).toISOString(), end_time: new Date(Date.now() + day * 86400000 + 3600000).toISOString() }))
  return <><PageTitle eyebrow="Practitioners / human support" title="You don’t have to do it alone." copy="When you want deeper support, find a licensed practitioner who fits the moment." />{error && <ErrorNote message={`Demo directory active · ${error}`} retry={load} />}<div className="grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><section><div className="grid gap-4 md:grid-cols-2">{busy && !therapists.length ? <div className="col-span-2 flex justify-center py-16"><Loader2 className="animate-spin text-mint" /></div> : therapists.map((person) => <article key={person._id || person.id} className="glass rounded-2xl p-5"><div className="flex gap-4"><div className="grid h-16 w-16 shrink-0 place-items-center rounded-2xl bg-gradient-to-br from-mint/20 to-lavender/20 text-mint"><UsersRound size={24} /></div><div><h3 className="font-display text-lg font-semibold">{person.name}</h3><p className="mt-1 text-xs text-slate-500">{person.experience_years} years · <Star className="mb-0.5 inline text-amber-300" size={11} fill="currentColor" /> {person.rating}</p><p className="mt-2 text-xs text-slate-400">{person.specializations?.slice(0, 2).join(' · ')}</p></div></div><p className="mt-4 line-clamp-2 text-xs leading-relaxed text-slate-600">{person.bio}</p><div className="mt-5 flex items-center justify-between border-t border-white/[.06] pt-4"><span className="font-mono text-xs text-lavender">${person.hourly_rate}<span className="text-slate-600">/session</span></span><Button onClick={() => open(person)} variant="secondary" className="px-3 py-2 text-xs">View times <ChevronRight size={13} /></Button></div></article>)}</div></section><section className="glass h-fit rounded-2xl p-6"><p className="font-mono text-[10px] uppercase tracking-[.2em] text-mint">Upcoming sessions</p><h2 className="mt-2 font-display text-2xl font-semibold">Your calendar.</h2><div className="mt-6 space-y-3">{appointments.length ? appointments.map((item) => <div key={item.appointment_id || item._id} className="rounded-xl border border-white/[.07] p-3"><div className="flex items-center justify-between"><p className="text-sm text-slate-300">{item.therapist_name}</p><button onClick={() => cancel(item.appointment_id)} className="text-slate-700 hover:text-rose-300"><X size={14} /></button></div><p className="mt-2 flex items-center gap-2 text-xs text-slate-500"><Calendar size={12} className="text-mint" />{new Date(item.start_time).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' })}</p></div>) : <EmptyState icon={Calendar} title="Nothing booked" copy="Your future sessions will show up here." />}</div></section></div>{selected && <div className="fixed inset-0 z-50 grid place-items-center bg-black/70 p-5 backdrop-blur-sm"><div className="glass max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-2xl p-6"><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-widest text-mint">Book a session</p><h2 className="mt-2 font-display text-2xl font-semibold">{selected.name}</h2></div><button onClick={() => setSelected(null)} className="text-slate-600"><X /></button></div><p className="mt-4 text-sm leading-relaxed text-slate-400">{selected.bio}</p><p className="mt-6 font-mono text-[10px] uppercase tracking-widest text-slate-600">Available times</p><div className="mt-3 grid gap-2 sm:grid-cols-2">{(selected.available_slots || demoSlots).slice(0, 6).map((item) => <button key={item.start_time} onClick={() => setSlot(item)} className={`rounded-xl border p-3 text-left text-xs ${slot?.start_time === item.start_time ? 'border-mint/50 bg-mint/10 text-mint' : 'border-white/[.08] text-slate-400'}`}><Clock3 className="mb-1 mr-1 inline" size={12} />{new Date(item.start_time).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' })}</button>)}</div><div className="mt-4"><TextArea label="Note for your practitioner (optional)" value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Anything you’d like them to know…" /></div><Button onClick={book} disabled={!slot || busy} className="mt-4 w-full">{busy ? <Loader2 className="animate-spin" size={14} /> : <Calendar size={14} />} Confirm session</Button></div></div>}</>
}

function CoinsPage() {
  const [data, setData] = useState({ balance: 0, transactions: [], goals: [], achievements: [], streak: {} }); const [spendOpen, setSpendOpen] = useState(false); const [amount, setAmount] = useState(100); const [error, setError] = useState('')
  const load = () => Promise.all([api('/coins/balance'), api('/coins/transactions'), api('/coins/daily-goals'), api('/coins/achievements'), api('/coins/streak')]).then(([balance, transactions, goals, achievements, streak]) => setData({ balance: balance.balance || 0, transactions: transactions || [], goals: goals || [], achievements: achievements || [], streak: streak || {} })).catch((err) => { setData((current) => ({ ...current, balance: current.balance || 1240, goals: [{ id: 1, title: 'Talk with AI companion', coins: 10, completed: true }, { id: 2, title: 'Write a journal entry', coins: 15, completed: false }, { id: 3, title: 'Complete mood check', coins: 5, completed: false }], achievements: [{ id: 1, title: 'First Steps', description: 'Started your mental health journey', unlocked: true }, { id: 2, title: 'Consistent Chatter', description: 'Chat for 7 days in a row', unlocked: false }] })); setError(err.message) })
  useEffect(() => { load() }, [])
  const spend = async () => { try { await api('/coins/spend', { method: 'POST', body: { amount: Number(amount), source: 'wellness_reward', description: 'Redeemed a ZenHeaven wellness reward' } }); setSpendOpen(false); load() } catch (err) { setError(err.message) } }
  return <><PageTitle eyebrow="Calm treasury / your economy" title="Reward the return." copy="Coins make the invisible work of showing up a little more visible." action={<Button onClick={() => setSpendOpen(true)} variant="violet"><WalletCards size={15} /> Redeem a reward</Button>} />{error && <ErrorNote message={`Demo ledger available · ${error}`} retry={load} />}<div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><section className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-lavender/20 via-[#172137] to-[#0b1720] p-7"><div className="absolute -right-20 -top-28 h-72 w-72 rounded-full bg-mint/10 blur-3xl" /><div className="relative"><p className="font-mono text-[10px] uppercase tracking-[.22em] text-lavender">Available balance</p><div className="mt-4 flex items-end gap-3"><span className="font-display text-6xl font-semibold">{data.balance.toLocaleString()}</span><span className="mb-2 text-xl text-lavender">◈</span></div><div className="mt-8 flex items-center gap-8"><div><p className="font-mono text-[9px] uppercase tracking-wider text-slate-500">Current streak</p><p className="mt-1 font-display text-xl font-semibold">{data.streak.current_streak || 0} <span className="text-xs text-slate-500">days</span></p></div><div><p className="font-mono text-[9px] uppercase tracking-wider text-slate-500">Next unlock</p><p className="mt-1 font-display text-xl font-semibold">100 <span className="text-xs text-slate-500">◈</span></p></div></div></div></section><section className="glass rounded-2xl p-6"><p className="font-mono text-[10px] uppercase tracking-[.22em] text-mint">Daily progress</p><h2 className="mt-2 font-display text-2xl font-semibold">Keep the rhythm.</h2><div className="mt-5 space-y-3">{data.goals.slice(0, 3).map((goal) => <div key={goal.id} className="flex items-center gap-3"><span className={`grid h-7 w-7 place-items-center rounded-lg ${goal.completed ? 'bg-mint text-void' : 'bg-white/[.06] text-slate-500'}`}>{goal.completed ? <Check size={13} /> : <Target size={13} />}</span><span className="flex-1 text-xs text-slate-400">{goal.title}</span><span className="font-mono text-[10px] text-lavender">+{goal.coins}</span></div>)}</div></section></div><div className="mt-6 grid gap-6 lg:grid-cols-2"><section className="glass rounded-2xl p-6"><div className="flex justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.22em] text-lavender">Milestones</p><h2 className="mt-2 font-display text-2xl font-semibold">Proof of practice.</h2></div><Award className="text-lavender" size={20} /></div><div className="mt-5 grid gap-2 sm:grid-cols-2">{data.achievements.map((item) => <div key={item.id} className={`rounded-xl border p-3 ${item.unlocked ? 'border-lavender/20 bg-lavender/[.06]' : 'border-white/[.06] opacity-50'}`}><div className="flex items-center gap-2"><Trophy size={14} className={item.unlocked ? 'text-lavender' : 'text-slate-600'} /><p className="text-xs font-medium text-slate-300">{item.title}</p></div><p className="mt-2 text-[10px] text-slate-600">{item.description}</p></div>)}</div></section><section className="glass rounded-2xl p-6"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.22em] text-mint">Ledger</p><h2 className="mt-2 font-display text-2xl font-semibold">Recent movement.</h2></div><RefreshCw onClick={load} className="cursor-pointer text-slate-600 hover:text-mint" size={16} /></div><div className="mt-5 space-y-2">{data.transactions.slice(0, 6).map((item, index) => <div key={item._id || index} className="flex items-center gap-3 border-b border-white/[.05] py-2"><span className="grid h-7 w-7 place-items-center rounded-lg bg-mint/10 text-mint">{item.transaction_type === 'spend' ? '−' : '+'}</span><div className="min-w-0 flex-1"><p className="truncate text-xs text-slate-400">{item.description}</p><p className="font-mono text-[9px] text-slate-700">{item.source}</p></div><span className="font-mono text-xs text-mint">{item.transaction_type === 'spend' ? '-' : '+'}{item.amount}</span></div>)}</div>{!data.transactions.length && <p className="mt-6 text-xs text-slate-600">Your first transaction will land here.</p>}</section></div>{spendOpen && <div className="fixed inset-0 z-50 grid place-items-center bg-black/70 p-5 backdrop-blur-sm"><div className="glass w-full max-w-sm rounded-2xl p-6"><div className="flex justify-between"><div><p className="font-mono text-[10px] uppercase tracking-widest text-lavender">Reward terminal</p><h2 className="mt-2 font-display text-2xl font-semibold">Spend with intention.</h2></div><button onClick={() => setSpendOpen(false)} className="text-slate-600"><X /></button></div><div className="mt-6 grid gap-2">{[['100', 'Premium insights'], ['150', 'Custom meditation'], ['200', 'Mindfulness course']].map(([cost, label]) => <button key={cost} onClick={() => setAmount(cost)} className={`flex items-center justify-between rounded-xl border p-3 text-left ${String(amount) === cost ? 'border-lavender/50 bg-lavender/10' : 'border-white/[.08]'}`}><span className="text-sm text-slate-300">{label}</span><span className="font-mono text-xs text-lavender">{cost} ◈</span></button>)}</div><Button onClick={spend} disabled={data.balance < Number(amount)} variant="violet" className="mt-5 w-full"><CircleDollarSign size={14} /> Confirm redemption</Button>{data.balance < Number(amount) && <p className="mt-2 text-center text-[10px] text-rose-300">Keep going—your balance is still growing.</p>}</div></div>}</>
}

function App() {
  return <AuthProvider><Routes><Route path="/" element={<Landing />} /><Route path="/login" element={<AuthPage mode="login" />} /><Route path="/register" element={<AuthPage mode="register" />} /><Route path="*" element={<Protected><AppShell><Routes><Route path="/dashboard" element={<Dashboard />} /><Route path="/chat" element={<><PageTitle eyebrow="Talk space / private support" title="You can say it here." copy="A quiet, intelligent space to untangle what’s on your mind." /><Chat /></>} /><Route path="/journal" element={<Journal />} /><Route path="/books" element={<Books />} /><Route path="/music" element={<Music />} /><Route path="/therapists" element={<Therapists />} /><Route path="/coins" element={<CoinsPage />} /><Route path="*" element={<Navigate to="/dashboard" replace />} /></Routes></AppShell></Protected>} /></Routes></AuthProvider>
}

export default App
